function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);
  ctx.lineWidth = 4;
  ctx.strokeStyle = 'black';
  ctx.beginPath();
  ctx.arc(W/2, H/2, 20, 0, 2 * Math.PI);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 20);
  ctx.lineTo(W/2, H/2 + 20 + 30 * (1 + Math.sin(t)));
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 20);
  ctx.lineTo(W/2 - 20 - 10 * Math.sin(t), H/2 + 40);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 20);
  ctx.lineTo(W/2 + 20 + 10 * Math.sin(t), H/2 + 40);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 50 + 30 * (1 + Math.sin(t)));
  ctx.lineTo(W/2 - 10 - 5 * Math.cos(t), H/2 + 70 + 20 * Math.sin(t));
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 50 + 30 * (1 + Math.sin(t)));
  ctx.lineTo(W/2 + 10 + 5 * Math.cos(t), H/2 + 70 + 20 * Math.sin(t));
  ctx.stroke();
  ctx.restore();
}
